SELECT DISTINCT p.PresidentName
FROM PresidentMarriage pm
JOIN PresidentHolding ph ON pm.PresidentName = ph.PresidentName
WHERE ph.RunnerUp IN (
    SELECT VicePresidentName FROM PresidentHolding
) AND ph.VicePresidentName IN (
    SELECT RunnerUp FROM PresidentHolding
);

SELECT ROUND(AVG(DATEDIFF(CURRENT_DATE, YEARBORN)), 2) AS AverageAge
FROM President
WHERE YearHolding = YearBorn AND MarriageStatus = 'Single';

SELECT PresidentName, YearEnd - YearHolding AS TermLength
FROM PresidentHolding
WHERE YearBorn > 1900 AND MarriageStatus = 'Married' ORDER BY TermLength DESC LIMIT 1;

SELECT PresidentName FROM President
WHERE PartyName IN (
    SELECT PartyName FROM Party
)
AND PresidentName IN (
    SELECT PresidentName FROM PresidentHolding
    WHERE YearEnd - YearHolding = MAX(YearEnd - YearHolding) OVER (PARTITION BY PartyName)
);

SELECT StateBorn, COUNT(DISTINCT MarriageStatus) AS "Number of Distinct Marriage Statuses"
FROM PresidentMarriage
GROUP BY StateBorn;

SELECT DISTINCT p1.PartyName AS PartyA, p2.PartyName AS PartyB
FROM President p1
JOIN Party p2 ON p1.StateBorn = p2.PartyName
WHERE p1.PartyName IN (
    SELECT PartyName FROM Party WHERE PartyName NOT IN (
        SELECT PartyName FROM President
    )
)
AND p2.PartyName IN (
    SELECT PartyName FROM Party WHERE PartyName NOT IN (
        SELECT PartyName FROM President
    )
)
AND EXISTS (
    SELECT 1 FROM PresidentMarriage pm1 JOIN President p2 ON pm1.PresidentName = p2.PresidentName AND p2.PartyName = p1.PartyName
    JOIN PresidentMarriage pm2 ON pm2.PresidentName = p2.PresidentName AND pm2.PartyName = p2.PartyName
    WHERE pm1.SpouseName = p2.PresidentName AND pm2.SpouseName = p2.PresidentName
)
AND EXISTS (
    SELECT 1 FROM PresidentHolding ph1 JOIN President p3 ON ph1.PresidentName = p3.PresidentName AND p3.PartyName = p1.PartyName
    JOIN PresidentHolding ph2 ON ph2.PresidentName = p3.PresidentName AND ph2.PartyName = p3.PartyName
    WHERE ph1.VicePresidentName = p3.PresidentName AND ph2.RunnerUp = p3.PresidentName
);

SELECT PresidentName, YearBorn, COUNT(*) AS TotalPresidents
FROM President
GROUP BY PresidentName, YearBorn;

